 c.strokeStyle='#bff18299';c.lineWidth=Math.max(3,w*.003);c.strokeRect(20,20,w-40,h-40);
 const isBanner=$('format').value==='banner',isStory=$('format').value==='story';const iw=isBanner?w*.42:w*.66;const ih=iw*(charImg.naturalHeight||1000)/(charImg.naturalWidth||400); const imgHeight=isBanner?h*1.05:isStory?h*.73:h*.82;const imgWidth=imgHeight*((charImg.naturalWidth||400)/(charImg.naturalHeight||1000));const x=isBanner?w*.55:(w-imgWidth)/2;const y=isBanner?h*.11:isStory?h*.1:h*.16;
 if(charImg.complete&&charImg.naturalWidth){c.save();c.shadowColor='#d1ff8a77';c.shadowBlur=48;c.drawImage(charImg,x,y,imgWidth,imgHeight);c.restore();drawCostume(x,y,imgWidth,imgHeight)}
 c.fillStyle='#bdf877';c.textAlign='left';c.font=`900 ${Math.round(w*.047)}px 'Barlow Condensed',sans-serif`;c.fillText('CRUMB',w*.06,h*.08);
